def transform(grid):
 from collections import Counter
 h,w=len(grid),len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if not grid[r][c] or (r,c) in seen: continue
   col=grid[r][c]; pts={(r,c)}; seen.add((r,c)); stack=[(r,c)]
   while stack:
    a,b=stack.pop()
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==col:
      seen.add((x,y));pts.add((x,y));stack.append((x,y))
   objs.append((col,pts))
 counts=Counter(col for col,p in objs); main=counts.most_common(1)[0][0]
 sizes={len(p) for col,p in objs if col==main}
 out=[r[:] for r in grid]
 for col,p in objs:
  if col!=main and len(p) in sizes:
   for r,c in p:out[r][c]=0
 return out

